# vectors.py：看一个词的邻居，就知道它是什么
from collections import defaultdict, Counter
import math

texts = [
    "请 申请 账号", "请 申请 账户", "尽快 开通 账号", "尽快 开通 账户",
    "账号 被 锁定", "账户 被 锁定", "忘记 账号 密码", "忘记 账户 密码",
    "请 安装 工具", "请 部署 工具", "安装 失败 了", "部署 失败 了",
    "本地 安装 环境", "本地 部署 环境", "重新 安装 插件", "重新 部署 插件",
]
# 每个词的向量 = 它左右两边各出现过哪些词、各几次
vec = defaultdict(Counter)
for text in texts:
    ws = text.split()
    for i, w in enumerate(ws):
        for j in (i - 1, i + 1):
            if 0 <= j < len(ws):
                vec[w][ws[j]] += 1

def cosine(a, b):
    dot = sum(a[k] * b[k] for k in a)
    na = math.sqrt(sum(v * v for v in a.values()))
    nb = math.sqrt(sum(v * v for v in b.values()))
    return dot / (na * nb)

for word in ("账号", "安装"):
    sims = sorted(((cosine(vec[word], vec[o]), o) for o in vec if o != word), reverse=True)
    print(word, "最像：", [f"{o} {s:.2f}" for s, o in sims[:3]])

